CREATE TABLE sellable_plans (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type_id TEXT NOT NULL,
  region_id TEXT NOT NULL,
  isp_id TEXT NOT NULL,
  spec_id TEXT,
  duration_id TEXT NOT NULL,
  price_fen INTEGER NOT NULL CHECK(price_fen > 0),
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),
  total_slots INTEGER CHECK(total_slots IS NULL OR total_slots >= 0),
  occupied_slots INTEGER NOT NULL DEFAULT 0 CHECK(occupied_slots >= 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  CHECK(total_slots IS NULL OR occupied_slots <= total_slots)
);

-- SQLite UNIQUE treats each NULL as distinct, so a plain column-list UNIQUE
-- would not stop duplicate fixed-price plans (spec_id IS NULL). This
-- expression index makes the 5-tuple uniqueness NULL-safe.
CREATE UNIQUE INDEX idx_sellable_plans_unique_combo
  ON sellable_plans(type_id, region_id, isp_id, COALESCE(spec_id, ''), duration_id);
CREATE INDEX idx_sellable_plans_active ON sellable_plans(is_active);

CREATE TABLE sellable_plan_price_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  plan_id INTEGER NOT NULL REFERENCES sellable_plans(id) ON DELETE RESTRICT,
  old_price_fen INTEGER NOT NULL,
  new_price_fen INTEGER NOT NULL,
  changed_by_admin_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  changed_at TEXT NOT NULL
);
CREATE INDEX idx_plan_price_history_plan ON sellable_plan_price_history(plan_id);

CREATE TABLE coupons (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL COLLATE NOCASE,
  kind TEXT NOT NULL CHECK(kind IN ('fixed','percent')),
  amount_off_fen INTEGER CHECK(amount_off_fen IS NULL OR amount_off_fen > 0),
  percent_off INTEGER CHECK(percent_off IS NULL OR (percent_off >= 1 AND percent_off <= 99)),
  min_amount_fen INTEGER CHECK(min_amount_fen IS NULL OR min_amount_fen > 0),
  scope TEXT NOT NULL CHECK(scope IN ('all','plans')),
  starts_at TEXT NOT NULL,
  ends_at TEXT NOT NULL,
  max_redemptions INTEGER CHECK(max_redemptions IS NULL OR max_redemptions >= 0),
  redeemed_count INTEGER NOT NULL DEFAULT 0 CHECK(redeemed_count >= 0),
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),
  created_by_admin_id INTEGER NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(code),
  CHECK(
    (kind='fixed'   AND amount_off_fen IS NOT NULL AND percent_off IS NULL) OR
    (kind='percent' AND percent_off IS NOT NULL AND amount_off_fen IS NULL)
  ),
  CHECK(ends_at > starts_at),
  CHECK(max_redemptions IS NULL OR redeemed_count <= max_redemptions)
);
CREATE INDEX idx_coupons_active ON coupons(is_active);

CREATE TABLE coupon_plans (
  coupon_id INTEGER NOT NULL REFERENCES coupons(id) ON DELETE RESTRICT,
  plan_id INTEGER NOT NULL REFERENCES sellable_plans(id) ON DELETE RESTRICT,
  PRIMARY KEY (coupon_id, plan_id)
);
CREATE INDEX idx_coupon_plans_plan ON coupon_plans(plan_id);

CREATE TABLE coupon_redemptions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  coupon_id INTEGER NOT NULL REFERENCES coupons(id) ON DELETE RESTRICT,
  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,
  user_id INTEGER REFERENCES users(id) ON DELETE RESTRICT,
  discount_fen INTEGER NOT NULL CHECK(discount_fen > 0),
  redeemed_at TEXT NOT NULL,
  released_at TEXT,
  UNIQUE(order_id)
);
CREATE INDEX idx_coupon_redemptions_coupon ON coupon_redemptions(coupon_id);

-- Absolute local deadline for an unpaid order's inventory/coupon reservation,
-- set at creation to created_at + 30 minutes (matches alipay.ts timeoutExpress).
ALTER TABLE payments ADD COLUMN reserved_until TEXT;

